SELECT (DATE_TRUNC('DAY', "USAGE_DAY")) AS "TIME_BUCKET", SUM(CREDITS_USED) AS "PIPE_SERVERLESS_TASK_CREDITS" FROM (SELECT "TASK_NAME" AS TASK_NAME, "TASK_ID" AS TASK_ID, "DATABASE_NAME" AS DATABASE_NAME, "SCHEMA_NAME" AS SCHEMA_NAME, CAST((DATE_TRUNC('DAY', (TRY_TO_TIMESTAMP_NTZ("START_TIME")))) AS DATE) AS USAGE_DAY, (NULL) AS ACCOUNT_NAME /* The account these rows came from (see the ACCOUNT_OF shim). Grouped on, */ /* so a lake holding several accounts keeps their task days apart. */, (CAST(SUM("CREDITS_USED") AS DECIMAL(38, 9))) AS CREDITS_USED, COUNT(*) AS RUN_COUNT FROM serverless_task_history GROUP BY 1, 2, 3, 4, 5, 6) AS base GROUP BY (DATE_TRUNC('DAY', "USAGE_DAY")) ORDER BY "PIPE_SERVERLESS_TASK_CREDITS" DESC NULLS LAST, "TIME_BUCKET" LIMIT 100
